head.script:
scwin.init = function() {
    var jsonData = [{
        "col1": "test1",
        "col2": "가"
    }];
    dataList1.setJSON(jsonData);
};
scwin.btn_onclick = function(e) {
    vl = grd.getColumnOrder();
    //alert(grd.getColumnOrder());
};
scwin.btn2_onclick = function(e) {
    vl1 = grd.getColumnOrder(true);
    //alert(grd.getColumnOrder(true));
};
scwin.btn3_onclick = function(e) {
    grd.setColumnOrder(["1", "2", "0"]);
};
scwin.btn4_onclick = function(e) {
    grd.setColumnOrder(["col1", "col2"]);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 get Number 버튼을 클릭한다.
    //1. Click the get Number button in your browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. '0,1,2' 팝업이 생성된다.
    // 1. '0,1,2' popup is generated.
    WebSquare.wUnit.addCommand("assert", "vl.toString() == '0,1,2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. get Name 버튼을 클릭한다.
    //2. Click the get Name button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 'col1,col2' 팝업이 생성된다. (그전버전에서는 'col1,col2,col2' 라고 생성되었음) 
    //2. A popup 'col1, col2' is created. (Previous versions generated 'col1, col2, col2')
    WebSquare.wUnit.addCommand("assert", "vl1.toString() == 'col1,col2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. setColimnOrder(Number) 버튼을 클릭한다.
    //3. Click the setColimnOrder (Number) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. name2 / name1 으로 정렬된다.
    //3. It is sorted by name2 / name1.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_column3').nextElementSibling.id == $p.id+'grd_column5'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. get Number 버튼을 클릭한다.
    //4. Click the get Number button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. '1,2,0' 팝업이 생성된다.
    //4. A pop-up of '1,2,0' is created.
    WebSquare.wUnit.addCommand("assert", "vl.toString() == '1,2,0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. get Name 버튼을 클릭한다.
    //5. Click the get Name button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 5. 'col2,col1' 팝업이 생성된다.
    //5. The 'col2, col1' popup is created.
    WebSquare.wUnit.addCommand("assert", "vl1.toString() == 'col2,col1'", "true");
    //Test step 6. setColimnOrder(Name) 버튼을 클릭한다.
    //6. Click the setColimnOrder (Name) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 6. 다시 name1 / name2 으로 정렬된다.
    //6. It is sorted by name1 / name2 again.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_column5').nextElementSibling.id == $p.id+'grd_column3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 7. get Number 버튼을 클릭한다.
    //7. Click the get Number button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 7. '0,1,2' 팝업이 생성된다.
    //7. '0,1,2' popup is generated.
    WebSquare.wUnit.addCommand("assert", "vl.toString() == '0,1,2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 8. get Name 버튼을 클릭한다.
    //8. Click the get Name button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 8. 'col1,col2' 팝업이 생성된다.
    //8. A popup 'col1, col2' is created.
    WebSquare.wUnit.addCommand("assert", "vl1.toString() == 'col1,col2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    var vl, vl1;
    window.vl = undefined;
    window.vl1 = undefined;
    scwin.init();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 07-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
